    zend_string *result = NULL;
    zip_file *zf;

    ZEND_FETCH_RESOURCE(zf, zip_file*, &zip_entry, -1, "zip entry", le_zip_entry);

    if (len <= 0) {
        len = 1024;
    }

    char *buffer = emalloc(len + 1);
    ssize_t bytes_read = zip_fread(zf, buffer, len);

    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
